right:
@import 'c/ihStyles';

.usage {
    display: flex;
    flex-direction: column;
    gap: 14px;
}
.bar {
    display: flex;
    align-items: center;
    gap: 10px;
}
.tile {
    cursor: default;
}
.tile:hover {
    border-color: var(--ih-line);
}
.meter {
    display: block;
    height: 6px;
    margin: 6px 0 2px;
    border-radius: 3px;
    background: var(--ih-line);
    overflow: hidden;
}
.meter-fill {
    display: block;
    height: 100%;
    border-radius: 3px;
    background: var(--ih-brand);
}
.block {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.block-title {
    font-size: 15px;
    font-weight: 700;
    margin: 0;
}
.table-box {
    overflow-x: auto;
}
.cell {
    vertical-align: top;
}
.note {
    margin: 0;
}
.flag {
    color: var(--ih-warn-ink);
    font-weight: 600;
}
.ok {
    color: var(--ih-ok);
}
.quiet {
    color: var(--ih-quiet);
}
